-- Replace the Praxxt-drafted rubrics with published, validated instruments

-- wherever one is free to use: Mini-CEX (medicine, physician assistant),

-- MTCCP (physiotherapy, CC BY 4.0) and AMSAT (midwifery, CC BY). Pharmacy

-- keeps its draft, now labelled as unvalidated. Item wording is verbatim

-- from each instrument's published form.

UPDATE "DisciplineTemplate"
SET "name" = 'Mini-CEX (Medicine)',
    "description" = 'Mini-Clinical Evaluation Exercise: six clinical skills plus overall competence, each rated 1–9 (1–3 unsatisfactory, 4–6 satisfactory, 7–9 superior). Validated, openly published.',
    "rubric" = '{"scaleLevels":[{"value":1,"label":"1 – Unsatisfactory"},{"value":2,"label":"2 – Unsatisfactory"},{"value":3,"label":"3 – Unsatisfactory"},{"value":4,"label":"4 – Satisfactory"},{"value":5,"label":"5 – Satisfactory"},{"value":6,"label":"6 – Satisfactory"},{"value":7,"label":"7 – Superior"},{"value":8,"label":"8 – Superior"},{"value":9,"label":"9 – Superior"}],"notAssessedLabel":"Not observed","source":"Mini-Clinical Evaluation Exercise (Mini-CEX), American Board of Internal Medicine. Norcini JJ, Blank LL, Duffy FD, Fortna GS. The mini-CEX: a method for assessing clinical skills. Ann Intern Med. 2003;138(6):476-481.","dimensions":[{"key":"CLINICAL_SKILLS","label":"Clinical skills","subDimensions":[{"key":"MEDICAL_INTERVIEWING","label":"Medical interviewing skills"},{"key":"PHYSICAL_EXAMINATION","label":"Physical examination skills"},{"key":"HUMANISTIC_QUALITIES","label":"Humanistic qualities / professionalism"},{"key":"CLINICAL_JUDGMENT","label":"Clinical judgment"},{"key":"COUNSELING","label":"Counseling skills"},{"key":"ORGANIZATION_EFFICIENCY","label":"Organization / efficiency"}]},{"key":"OVERALL","label":"Overall","excludeFromScore":true,"subDimensions":[{"key":"OVERALL_CLINICAL_COMPETENCE","label":"Overall clinical competence"}]}]}'::jsonb,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE "id" = '00000000-0000-0000-0000-000000000003';

UPDATE "DisciplineTemplate"
SET "name" = 'Mini-CEX (Physician Assistant)',
    "description" = 'Mini-Clinical Evaluation Exercise, widely used in physician assistant programs: six clinical skills plus overall competence, each rated 1–9 (1–3 unsatisfactory, 4–6 satisfactory, 7–9 superior). Validated, openly published.',
    "rubric" = '{"scaleLevels":[{"value":1,"label":"1 – Unsatisfactory"},{"value":2,"label":"2 – Unsatisfactory"},{"value":3,"label":"3 – Unsatisfactory"},{"value":4,"label":"4 – Satisfactory"},{"value":5,"label":"5 – Satisfactory"},{"value":6,"label":"6 – Satisfactory"},{"value":7,"label":"7 – Superior"},{"value":8,"label":"8 – Superior"},{"value":9,"label":"9 – Superior"}],"notAssessedLabel":"Not observed","source":"Mini-Clinical Evaluation Exercise (Mini-CEX), American Board of Internal Medicine. Norcini JJ, Blank LL, Duffy FD, Fortna GS. The mini-CEX: a method for assessing clinical skills. Ann Intern Med. 2003;138(6):476-481.","dimensions":[{"key":"CLINICAL_SKILLS","label":"Clinical skills","subDimensions":[{"key":"MEDICAL_INTERVIEWING","label":"Medical interviewing skills"},{"key":"PHYSICAL_EXAMINATION","label":"Physical examination skills"},{"key":"HUMANISTIC_QUALITIES","label":"Humanistic qualities / professionalism"},{"key":"CLINICAL_JUDGMENT","label":"Clinical judgment"},{"key":"COUNSELING","label":"Counseling skills"},{"key":"ORGANIZATION_EFFICIENCY","label":"Organization / efficiency"}]},{"key":"OVERALL","label":"Overall","excludeFromScore":true,"subDimensions":[{"key":"OVERALL_CLINICAL_COMPETENCE","label":"Overall clinical competence"}]}]}'::jsonb,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE "id" = '00000000-0000-0000-0000-000000000006';

UPDATE "DisciplineTemplate"
SET "name" = 'MTCCP (Physiotherapy)',
    "description" = 'Measurement Tool for Clinical Competencies in Physiotherapy: 10 clinical reasoning items (60%) and 10 professional behavior items (40%), each rated 1 (very poor) to 5 (excellent). Validated, CC BY 4.0.',
    "rubric" = '{"scaleLevels":[{"value":1,"label":"Very poor"},{"value":2,"label":"Poor"},{"value":3,"label":"Fair"},{"value":4,"label":"Good"},{"value":5,"label":"Excellent"}],"source":"Measurement Tool for Clinical Competencies in Physiotherapy (MTCCP). Torres-Narváez MR, Vargas-Pinilla OC, Rodríguez-Grande EI. Validity and reproducibility of a tool for assessing clinical competencies in physical therapy students. BMC Med Educ. 2018. doi:10.1186/s12909-018-1377-x. Licensed CC BY 4.0; adapted by removing a Colombia-specific legal reference from item PB2’s guidance.","dimensions":[{"key":"CLINICAL_REASONING","label":"Clinical reasoning (60%)","weight":0.6,"subDimensions":[{"key":"CR1","label":"Produces an initial hypothesis of the user clinical condition based on the available information: Clinical record, observation, and interview.","description":"Integrates concepts of the basic and disciplinary sciences to select and understand in the expected time the available information referring to the user’s situation and his/her background.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"CR2","label":"Selects the tests and measures consistent with the user’s priorities and the best available scientific evidence.","description":"Bases his/her test and measures selection on the psychometrical properties and the specificity of the tools, as well as the resource availability.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"CR3","label":"Applies skillfully the selected tests and measures.","description":"Applies the tests and conducts the examinations with the proper technique: expected verbal commands, hand contact and positions (of user and physiotherapist) expected in each case.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"CR4","label":"Analyses the obtained information to produce a diagnosis of the user’s functional condition.","description":"Argues his/her clinical judgement on the user’s condition in terms of deficiencies, activity limitations and participation constraints, based in the evaluation.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"CR5","label":"Determines the physiotherapeutic prognosis that allows him/her to project goals and treatment plan.","description":"Argues the optimal recovery level that can be achieved and the required time to reach it based on the knowledge of the user’s conditions, the underlying pathology, the available evidence and the facilitators and barriers of the actual context.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"CR6","label":"Establishes the general objective of the treatment plan according to the user’s diagnosis and prognosis.","description":"Establishes the goal of the specific functional reach for the user’s condition.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"CR7","label":"Structures the treatment plan taking the available resources and evidence into account.","description":"Argues based on the physiological mechanisms of the treatment plan, defining the intervention intensity, frequency, volume, mode, method, and duration grounded on the user’s needs, preferences, and particularities, on the general objective, the evidence and the available resources.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"CR8","label":"Applies skillfully the therapeutic strategies established in the treatment plan.","description":"Applies the intervention modalities with the proper technique: verbal commands, hand contact and positions (of user and physiotherapist) expected for each case.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"CR9","label":"Carries out education strategies for body and movement in order to fulfill the set objectives.","description":"Argues the education strategies selection and implementation aimed at users and caregivers as part of the treatment plan.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"CR10","label":"Evaluates the impact of his/her interventions and makes the required adjustments to the treatment based on the behavior of the relevant clinical variables.","description":"Argues the changes made to the treatment plan based on the findings of the reassessment of the established outcome measurements.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}}]},{"key":"PROFESSIONAL_BEHAVIOR","label":"Professional behavior (40%)","weight":0.4,"subDimensions":[{"key":"PB1","label":"Minimizes the actual risk of damage in itself and the population it serves.","description":"Uses the basic bio-security norms and implements the institution’s patient security policy; recognizes and minimizes the risks inherent to the test implementation, of the measurements and interventions taking care of the body mechanics.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"PB2","label":"Meets the ethical and bioethical principles of the professional practice.","description":"Acts responsibly; approaches with moral reasoning the ethical dilemmas; takes into account the needs and values of others; is accurate and consistent doing what he/she says he/she is going to do; manages information confidentially; and adheres to the ethical guidelines specific to physiotherapy considering the user’s cultural context.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"PB3","label":"Uses efficiently and adequately the physical and technological resources available in the practice setting.","description":"Adequately uses software, hardware and elements intended to provide physiotherapy services (electrotherapy equipment, physical means, gymnasium); justifies the use of resources in accordance with the requirements of service, user and practice; knows the equipment technical specifications he/she uses; recognizes the proper functioning of the equipment he/she uses; and reports in due course equipment failures.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"PB4","label":"Has an assertive verbal, nonverbal and written communication.","description":"Communicates congruently and balanced expressing his/her convictions and defending his/her positions with argumentations; uses a posture that facilitates communications; and keeps eye contact with his/her interlocutor.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"PB5","label":"Establishes interdisciplinary academic relations for the benefit of his/her training process and of the user’s assistance.","description":"Interacts opportunely and respectfully with professionals in order to improve his/her professional performance and the clinical decision-making; participates in the working group considering his/her objective of study.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"PB6","label":"Shows initiative and leadership in managing knowledge and organizing activities within the practice.","description":"Proposes improvement actions; recognizes the own and the work group’s abilities within the context of the requirements of the practice setting; assertively solves situations that demand an immediate response.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"PB7","label":"Shows continuous commitment to improvement for the personal and professional development.","description":"Accepts, integrates and applies the received feedback given by the clinical instructor or the professionals in a constructive manner aiming at improving his/her performance; takes responsibly his/her learning and performs self-assessment of his/her own behavior.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"PB8","label":"Bases his/her professional undertaking on the best available scientific evidence.","description":"Is proficient in searching scientific literature to support his/her interventions and carries out a critical analysis of it in order to apply the knowledge produced by these studies to the assisted population.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"PB9","label":"Fully assumes the undertaken commitments typical of the professional performance and his/her role as a student.","description":"Composes documents and carries out activities under his/her charge all in a timely and a good quality basis, and in consistency with the education project of the academic program.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}},{"key":"PB10","label":"Takes part meeting efficiency and quality in the administrative activities of his/her practice.","description":"Keeps updated the documentation related to the conducted interventions (clinical record, indicators, invoicing and inventory) in accordance with the institutional guidelines of the specific practice setting and of the University.","levelHints":{"1":"Requires permanent clinical instructor presence.","2":"Requires frequent clinical instructor presence.","3":"Requires occasional clinical instructor presence.","4":"Requires minimal clinical instructor presence.","5":"Does not require clinical instructor presence."}}]}]}'::jsonb,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE "id" = '00000000-0000-0000-0000-000000000004';

UPDATE "DisciplineTemplate"
SET "name" = 'Pharmacy (Praxxt draft, not validated)',
    "description" = 'Praxxt''s own draft: pharmaceutical care, dispensing, patient counselling and professional practice, each scored 1 (Below expectations) to 4 (Exceeds expectations). Not a validated instrument — replace with your program''s approved tool.',
    "updatedAt" = CURRENT_TIMESTAMP
WHERE "id" = '00000000-0000-0000-0000-000000000005';

INSERT INTO "DisciplineTemplate" ("id", "name", "description", "rubric", "extraLogFields", "updatedAt")
VALUES (
    '00000000-0000-0000-0000-000000000007',
    'AMSAT (Midwifery)',
    'Australian Midwifery Standards Assessment Tool: 25 items across the 7 midwife standards for practice, each rated 1 (unsatisfactory) to 5 (excellent), plus a global rating. Validated, CC BY.',
    '{"scaleLevels":[{"value":1,"label":"Unsatisfactory"},{"value":2,"label":"Limited"},{"value":3,"label":"Satisfactory"},{"value":4,"label":"Proficient"},{"value":5,"label":"Excellent"}],"notAssessedLabel":"Not assessed","source":"Australian Midwifery Standards Assessment Tool (AMSAT), Australian College of Midwives. Licensed CC BY. Rate against the minimum competency level expected for the student’s level of training; a rating of 1 or 2 means the competency statement has not been achieved.","dimensions":[{"key":"STANDARD_1","label":"Standard 1: Promotes health and wellbeing through evidence-based midwifery practice","subDimensions":[{"key":"S1_1","label":"Works in partnership with the woman to identify what is important to her, inform decision making, and promote self-determination","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S1_2","label":"Sources, critically evaluates and reflects on relevant evidence to inform safe, quality practice","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S1_3","label":"Applies primary health care principles to address individual, community, and public health issues","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S1_4","label":"Promotes equitable access to appropriate midwifery care","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S1_5","label":"Demonstrates ability to initiate health education and provide resources to enable women to influence their own health outcomes","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}}]},{"key":"STANDARD_2","label":"Standard 2: Engages in professional relationships and respectful partnerships","subDimensions":[{"key":"S2_1","label":"Participates as an active member of the healthcare team to promote optimum health outcomes","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S2_2","label":"Demonstrates knowledge and understanding of the principles of cultural safety and provides culturally responsive woman-centered care","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S2_3","label":"Practises in a way that respects that family and community underpin the health of Aboriginal and/or Torres Strait Islander women and their families","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S2_4","label":"Acknowledges and manages personal values, beliefs, and power dynamics in midwifery to ensure equity, justice, non-judgmental, and non-discriminatory practice","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S2_5","label":"Practices within professional boundaries and demonstrates ethical conduct to ensure rights, privacy, and confidentiality","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}}]},{"key":"STANDARD_3","label":"Standard 3: Demonstrates the capability and accountability for midwifery practice","subDimensions":[{"key":"S3_1","label":"Recognises and practices within own midwifery scope, professional standards, relevant legislation, and local policy","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S3_2","label":"Demonstrates knowledge and accountability for own midwifery practice","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S3_3","label":"Consults, refers, documents appropriately and manages complexity in a timely manner to provide safe, quality care","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S3_4","label":"Demonstrates commitment to life-long learning of self and others","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S3_5","label":"Recognises and responds appropriately when own, or others’, quality/capability for practice is impaired","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}}]},{"key":"STANDARD_4","label":"Standard 4: Undertakes comprehensive assessments","subDimensions":[{"key":"S4_1","label":"Completes comprehensive and systematic assessments using appropriate and available resources, and accurately documents findings","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S4_2","label":"Critically analyses and interprets assessment data to inform and improve midwifery practice in partnership with the woman","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S4_3","label":"Accurately assesses the physical, social, emotional, cultural and spiritual needs of women, communities, and populations","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}}]},{"key":"STANDARD_5","label":"Standard 5: Develops a plan for midwifery practice","subDimensions":[{"key":"S5_1","label":"Collaboratively plans appropriate woman-centred care based on assessment findings to achieve optimal outcomes","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S5_2","label":"Identifies and accesses appropriate resources, including relevant health professionals or services, for planning woman-centred care","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S5_3","label":"Appropriately reviews and modifies planned care in partnership with the woman, and documents to facilitate optimal outcomes","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}}]},{"key":"STANDARD_6","label":"Standard 6: Provides safety and quality in midwifery practice","subDimensions":[{"key":"S6_1","label":"Recognises and acts on identifying emergency/urgent or unsafe situations, and initiates appropriate actions to meet optimal outcomes","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S6_2","label":"Works collaboratively as an effective team member by supporting, reflecting on, and incorporating feedback to improve midwifery practice","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}}]},{"key":"STANDARD_7","label":"Standard 7: Evaluates outcomes to improve midwifery practice","subDimensions":[{"key":"S7_1","label":"Evaluates, monitors, and reflects on practice and responds to feedback for continuing professional development to enable optimal outcomes for women and families","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}},{"key":"S7_2","label":"Develops, implements, reviews, and reflects on personal learning goals for professional growth and development","levelHints":{"1":"Not performed; direct close guidance and immediate feedback required.","2":"Inconsistent or below acceptable standard; continuous cues required, meaning of cues explored and clarified with student.","3":"Consistently performed at a satisfactory/pass level; frequent cues required, cues developed in partnership with student.","4":"Performed at a proficient standard; occasional cues required, based on student’s learning goals.","5":"Performed at an excellent standard; minimal cues required, based on student’s aspirations."}}]},{"key":"GLOBAL_RATING","label":"Global rating scale","excludeFromScore":true,"subDimensions":[{"key":"GLOBAL","label":"Relative to their stage of practice, the overall performance of this student in the clinical unit was"}]}]}'::jsonb,
    '[]'::jsonb,
    CURRENT_TIMESTAMP
)
ON CONFLICT ("id") DO NOTHING;

-- Move midwifery programs still on the shared Lasater rubric to AMSAT, but
-- only those with no evaluations yet, so no saved rating loses its rubric.

UPDATE "Program" p
SET "disciplineTemplateId" = '00000000-0000-0000-0000-000000000007', "updatedAt" = CURRENT_TIMESTAMP
WHERE p."disciplineTemplateId" = '00000000-0000-0000-0000-000000000001'
  AND p."name" ILIKE '%midwi%'
  AND NOT EXISTS (
    SELECT 1 FROM "CompetencyEvaluation" e
    JOIN "Rotation" r ON r."id" = e."rotationId"
    WHERE r."programId" = p."id"
  );
